steps.command:
printf '# CME-921: URL path canonicalization before authorization
merge_slashes on;

map $request_uri $cme921_block {
    default 0;
    "~*\.\."          1;
    "~*%%2[eE]"        1;
    "~*%%2[fF]"        1;
    "~*%%5[cC]"        1;
    "~*;[^/]*="        1;
}
' > /etc/nginx/conf.d/cme-921-canonicalization.conf
